import { inject } from '@angular/core';
import { AppSettingsService } from '../shared/business/services/app-settings.service';
import { lastValueFrom } from 'rxjs';
import { KeycloakService } from '../shared/business/services/keycloak.service';
import Keycloak from 'keycloak-js';
import { ConfigErrorHelper } from '../shared/business/helpers/config-error.helper';
import { StringHelper } from '../shared/business/helpers/string.helper';

export const getKeycloakConfig = async () => {
  const appSettingsService = inject(AppSettingsService);
  const keycloakService = inject(KeycloakService);

  const appSettings = await lastValueFrom(appSettingsService.loadConfig());
  const configError = ConfigErrorHelper.getErrorMessage(appSettings);
  if (!StringHelper.isNullOrEmpty(configError)) {
    return;
  }
  const keycloak = new Keycloak({
    url: appSettings?.keycloak?.authServerUrl!,
    realm: appSettings?.keycloak?.realm!,
    clientId: appSettings?.keycloak?.resource!
  });
  await keycloak.init({

    onLoad: 'login-required',
    checkLoginIframe: false,
    locale: 'de'
  });
  keycloakService.keycloak = keycloak;
};
