  }

  public hasRole(roles: Role[] | null | undefined): boolean {
    if (!Array.isArray(roles) || roles.length === 0) {
      return true;
    }
    if (!this.keycloak?.authenticated) {
      return false;
    }
    const resource = this.appSettingsService.config?.keycloak?.resource;
    const resourceAccess = this.keycloak?.tokenParsed?.resource_access;
    if (resource && resourceAccess && resource in resourceAccess) {
      const resourceRoles = resourceAccess[resource].roles || [];
      return resourceRoles.some(x => (roles as any).includes(x));
    }
    return false;
  }

  public getUserName(): string | null {
    if (!this.keycloak?.tokenParsed) {
      return null;
    }
    const token: any = this.keycloak.tokenParsed!;
    return `${token.given_name} ${token.family_name}`;
  }

}

